function explanation(d=drive){
 const s=d.last,net=s.M-s.T,phase=Math.abs(s.n)<.5?'in stilstand':Math.abs(s.alpha)<.2?'ongeveer in dynamisch evenwicht':s.n*s.alpha>0?'aan het versnellen':'aan het vertragen';
 let txt=`De as is ${phase}. M = ${fmt(s.M)} Nm en T = ${fmt(s.T)} Nm geven M − T = ${fmt(net)} Nm. Met J = ${fmt(s.J,3)} kg·m² volgt α = ${fmt(s.alpha)} rad/s². `;
 if(s.q==='Grens')txt+='Het punt ligt op een kwadrantgrens: bij stilstand of nul koppel is motor- of generatorbedrijf nog niet eenduidig.';
 else txt+=`Het werkingspunt ligt in kwadrant ${s.q}: ${s.M*s.n>0?'motorisch bedrijf; de motor levert mechanisch vermogen.':'generatorisch bedrijf; de machine neemt mechanische energie op.'}`;
 if(d.mode==='coast')txt+=' De omvormer levert na het uitdoven van het koppel geen actief remkoppel. De passieve belasting voert de rotatie-energie af.';
 else if(s.n*s.alpha<0&&s.M*s.n>0)txt+=' De motor vertraagt toch met positief mechanisch vermogen: de last remt sterker dan de motor aandrijft. Vertragen betekent niet automatisch generatorbedrijf.';
 if(Math.abs(s.M)>.97*(d.limit||params.maxTorque))txt+=' De koppelgrens is bereikt; de werkelijke snelheid kan de gevraagde ramp niet volgen.';
 if(s.Pel<0)txt+=d.p.regen==='resistor'?` Er gaat circa ${fmt(s.Pbrake,0)} W naar de remweerstand; het net krijgt in dit model geen remenergie terug.`:' De regeneratieve netomvormer kan het negatieve actieve vermogen terugvoeren naar het net.';
 return txt;
}
function paint(force=false){
 if(!drive)return;const s=drive.last;
 for(const [key,,,d] of metricSpec)$('m-'+key).textContent=key==='q'?s.q:fmt(key==='target'?targetFor(params):key==='J'?params.J:s[key],d);
 $('m-target').closest('.metric').querySelector('.metric-label').textContent=params.controlMode==='frequency'?'Verwacht belast toerental':'Ingesteld toerental';
 $('clock').textContent=fmt(drive.t)+' s';$('run-status').textContent=(playing?'● Actief':drive.t>0?'Ⅱ Gepauzeerd':'● Gereed');$('run-status').style.color=playing?'var(--green)':'var(--muted)';$('pause').textContent=playing?'Ⅱ Pauze':'▶ Verder';
 const motion=Math.abs(s.n)<.5?'Stilstand':s.M*s.n<-.1?'Generatorbedrijf':Math.abs(s.alpha)<.2?'Stationair':s.n*s.alpha>0?'Versnelt':'Vertraagt';$('plant-status').textContent=motion;$('shaft-caption').textContent=s.n>=0?'Draairichting vooruit':'Draairichting achteruit';$('drive-screen').textContent=fmt(s.f,1)+' Hz';$('power-flow').textContent=s.Pgrid<-.1?'Terug naar net':s.Pbrake>.1?'Naar remweerstand':s.Pgrid>.1?'Net → motor':'Geen netvermogen';$('energy-arrow').firstChild.textContent=s.Pgrid<0?'←':'→';$('load-motion').textContent=M.loadNames[params.loadType];$('live-explanation').textContent=(!playing?`Dit is het laatst geregistreerde punt bij t = ${fmt(s.t)} s. Werkelijke n, M en α horen bij die integratiestap; gewijzigde instellingen worden bij Start of Stap verder doorgerekend. `:'')+explanation();
 if(activeTab==='dynamiek'||force){const data=drive.data;charts.quad.setData([series(data,'n','Werkingspunt',palette[0],'M')]);charts.speed.setData([series(data,'n','Werkelijk n'),{...series(data,'ref',params.controlMode==='frequency'?'Synchroon toerental van de ramp':'Rampreferentie',palette[1]),dashed:true}]);charts.torque.setData([series(data,'M','Motorkoppel'),series(data,'T','Belastingskoppel',palette[1])]);charts.alpha.setData([series(data,'alpha','Hoekversnelling',palette[3])]);}
}
function animate(now){
 const wall=Math.min(.1,(now-(rafTime||now))/1000);rafTime=now;
 if(playing){accumulator+=wall*speed;while(accumulator>=.002&&drive.t<params.duration-.001){drive.step(.002);accumulator-=.002;}if(drive.t>=params.duration-.001){playing=false;notify('Opnameduur bereikt. Registreer deze actie of herstart een nieuw experiment.');reportActual(drive,'Afgeronde labo-actie');}}
 if(playing)angle+=M.rad(drive.last.n)*wall;
 $('shaft').style.transform=`rotate(${angle}rad)`;$('fan').style.transform=`rotate(${angle*.17}rad)`;
 if(now-lastPaint>80){paint();lastPaint=now;}requestAnimationFrame(animate);
}
function csvEscape(v){return '"'+String(v??'').replace(/"/g,'""')+'"';}
const csvFields=['t','n','ref','target','M','T','alpha','J','Pm','Pel','Pgrid','Pbrake','I','U','PF','f','ns','slip','q','mode','impulse'];
const csvUnits=['s','tpm','tpm','tpm','Nm','Nm','rad/s2','kg m2','W','W','W','W','A','V','-','Hz','tpm','-','-','-','N m s'];
function csvFor(runs){
 const lines=['# DriveLab lokale simulatie; elektrische grootheden zijn schattingen.'];
 for(const r of runs){lines.push('# '+r.name,'# parameters='+JSON.stringify(r.params),'# gebeurtenissen='+JSON.stringify(r.events||[]));}
 lines.push(['opname',...csvFields.map((f,i)=>`${f} (${csvUnits[i]})`)].map(csvEscape).join(';'));
 for(const r of runs)for(const s of r.data)lines.push([r.name,...csvFields.map(f=>typeof s[f]==='number'?s[f].toPrecision(12).replace('.',','):s[f])].map(csvEscape).join(';'));
 return '\ufeff'+lines.join('\r\n');
}
function currentRun(){return {name:$('record-name').value.trim()||'Dynamische actie',params:{...params},events:drive.events,data:drive.data.map(s=>({...s})),created:new Date().toISOString()};}
function downloadCSV(runs,name){window.LabDownload(new Blob([csvFor(runs)],{type:'text/csv;charset=utf-8'}),name+'.csv');}
function persistSaved(){try{localStorage.setItem('drivelab-recordings-v1',JSON.stringify(saved));return true;}catch(e){notify('Opname in deze sessie bewaard. Browseropslag is niet beschikbaar of vol; download JSON om de data te bewaren.');return false;}}
function renderRecords(){
 const list=$('record-list');list.replaceChildren();if(!saved.length){list.innerHTML='<p class="muted">Nog geen opnamen. Registreer een actie om apart te bewaren en te vergelijken.</p>';return;}
 for(const r of saved){const row=document.createElement('div');row.className='record-row';row.innerHTML=`<input type="checkbox" aria-label="${esc(r.name)} vergelijken" ${selected.has(r.id)?'checked':''}><strong>${esc(r.name)}</strong><small>${fmt(r.data.at(-1).t,1)} s · J ${fmt(r.params.J,3)}</small><button data-action="view">Bekijk</button><button data-action="csv">CSV</button><button data-action="remove" aria-label="Opname verwijderen">×</button>`;row.querySelector('input').onchange=e=>e.target.checked?selected.add(r.id):selected.delete(r.id);row.querySelector('[data-action=view]').onclick=()=>showRecord(r);row.querySelector('[data-action=csv]').onclick=()=>downloadCSV([r],r.name);row.querySelector('[data-action=remove]').onclick=()=>{saved=saved.filter(z=>z!==r);selected.delete(r.id);persistSaved();renderRecords();};list.append(row);}
}
function saveRun(){if(drive.data.length<3){notify('Laat eerst een korte simulatie lopen.');return;}if(saved.length>=8){notify('Maximaal 8 opnamen. Exporteer en verwijder een oudere opname om ruimte te maken.');return;}const r={...currentRun(),id:'r'+Date.now()};saved.push(r);persistSaved();renderRecords();showRecord(r);reportActual(drive,'Bewaarde labo-actie');notify('Afzonderlijke actie bewaard. De eigen M,n-grafiek staat bij de registraties.');}
function showRecord(r){activeRecord=r;charts.saved.title=r.name;charts.saved.host.querySelector('h3').textContent=r.name;charts.saved.setData([series(r.data,'n',r.name,palette[0],'M')],{reset:true});charts.compare.setData([series(r.data,'n',r.name)],{reset:true});$('compare-summary').textContent=`${r.name} · T0 ${fmt(r.params.T0)} Nm · J ${fmt(r.params.J,3)} kg·m² · stopwijze ${r.params.stopMode} · ${r.data.length} meetpunten`;$('compare-summary').className='control-note';}
function compareRuns(){const runs=saved.filter(r=>selected.has(r.id));if(!runs.length){notify('Selecteer eerst twee tot vier opnamen met de selectievakjes.');return;}if(runs.length>4){notify('Selecteer maximaal vier opnamen om de grafiek leesbaar te houden.');return;}charts.compare.setData(runs.map((r,i)=>series(r.data,'n',r.name,palette[i])),{reset:true});charts.saved.setData(runs.map((r,i)=>series(r.data,'n',r.name,palette[i],'M')),{reset:true});$('compare-summary').innerHTML=`<table class="data-table"><thead><tr><th>Opname</th><th>J (kg·m²)</th><th>T0 (Nm)</th><th>Piek |M| (Nm)</th><th>Eind n (tpm)</th></tr></thead><tbody>${runs.map(r=>{const a=M.metrics(r.data,r.params.target);return `<tr><td>${esc(r.name)}</td><td>${fmt(r.params.J,3)}</td><td>${fmt(r.params.T0)}</td><td>${fmt(a.maxM)}</td><td>${fmt(a.final,0)}</td></tr>`;}).join('')}</tbody></table>`;charts.saved.host.querySelector('h3').textContent='Vergelijking van opgeslagen M,n-trajecten';}

const applications={
 constant:{name:'Transportband',formula:'T = T₀ · factor',text:'Bij een ongeveer constante transportkracht en vaste rolstraal blijft het koppel vrijwel constant. Meer productmassa of helling verhoogt T₀. Het mechanisch vermogen neemt evenredig met toerental toe.',params:[['T0','Basiskoppel T₀ (Nm)',0,20,.1]]},
 linear:{name:'Viskeuze machinebelasting',formula:'T = (T₀ + b · |ω|) · factor',text:'Een viskeuze rem of een mechanisme met overwegend viskeuze wrijving vraagt meer koppel bij hogere snelheid. b hangt onder meer af van viscositeit en geometrie. Een gewone ventilator wordt beter door een kwadratische wet benaderd.',params:[['T0','Constant deel T₀ (Nm)',0,15,.1],['b','Viskeuze coëfficiënt b (Nms)',0,.15,.001]]},
 quadratic:{name:'Ventilator of centrifugaalpomp',formula:'T = (T₀ + k · ω²) · factor',text:'Bij vergelijkbare stromingscondities is het koppel ongeveer evenredig met het kwadraat van de snelheid; vermogen groeit ongeveer met de derde macht. k vat de geometrie, vloeistofdichtheid en installatiecondities samen.',params:[['T0','Constant deel T₀ (Nm)',0,10,.1],['k','Kwadratische factor k',0,.001,.00001]]},
 breakaway:{name:'Machine met hoog losbreekkoppel',formula:'T = [T₀ + (Tlos − T₀)₊ exp(−(|ω|/ωs)²) + b|ω|] · factor',text:'Een zwaar belaste transporteur of een vastzittende machine moet eerst statische wrijving overwinnen. Tlos is de losbreekdrempel; bij beweging daalt het extra wrijvingskoppel. Zonder voldoende motorkoppel blijft de as staan.',params:[['T0','Glijkoppel T₀ (Nm)',0,15,.1],['breakaway','Losbreekdrempel (Nm)',0,30,.5],['breakSpeed','Stribeck-snelheid ωs (rad/s)',.1,40,.5],['b','Viskeuze coëfficiënt b',0,.15,.001]]},
 power:{name:'Wikkelmachine met constante bandsnelheid',formula:'T = min(P₀ / |ω|, Tlimiet) · factor',text:'Bij constante trekkracht en constante lineaire bandsnelheid is het procesvermogen constant. Door een veranderende rolstraal variëren het koppel en toerental omgekeerd. Dit geldt binnen het procesgebied; nabij nul begrenst deze simulator het koppel.',params:[['power','Procesvermogen P₀ (W)',0,2000,25],['powerCap','Koppellimiet bij lage snelheid (Nm)',.1,30,.5]]}
};
function appSVG(type){
 const frame='<rect x="18" y="70" width="160" height="8" rx="3" fill="#365773"/><path d="M35 78v12m125-12v12" stroke="#557b98" stroke-width="6"/>';
 let shape;
 if(type==='quadratic')shape='<circle cx="100" cy="43" r="33" fill="#203f56" stroke="#62b9d8" stroke-width="2"/><g class="spin" fill="#79cce4"><path d="M100 42C72 10 140 4 105 42C147 19 150 80 105 48C118 87 54 90 96 48C48 62 51 4 100 42Z"/><circle cx="100" cy="43" r="7" fill="#163047"/></g>';
 else if(type==='power')shape='<g class="spin"><circle cx="100" cy="43" r="31" fill="#244761" stroke="#84beda" stroke-width="3"/><circle cx="100" cy="43" r="19" fill="none" stroke="#64a0bd" stroke-width="6"/><path d="M100 13v60m-30-30h60" stroke="#6ab3cb" stroke-width="3"/></g><path d="M130 38h55" stroke="#ffbc69" stroke-width="5"/>';
 else if(type==='linear')shape='<rect x="62" y="13" width="80" height="59" rx="5" fill="#23425a" stroke="#679bb4"/><g class="spin"><path d="M100 20v45m-15-28h30m-30 13h30" stroke="#6ad4ec" stroke-width="6"/></g><path d="M68 55q16-8 32 0t35 0" fill="none" stroke="#478bb1" stroke-width="4"/>';
 else shape='<rect x="28" y="44" width="145" height="23" rx="12" fill="#25455c" stroke="#678da7"/><path class="belt" d="M40 55h120" stroke="#7dbbd0" stroke-width="3"/><rect x="75" y="20" width="36" height="25" rx="3" fill="'+(type==='breakaway'?'#ac7944':'#7195b4')+'"/><path d="M78 28h30" stroke="#c9d9e4"/>';
 return `<svg viewBox="0 0 200 100" role="img" aria-label="Animatie van ${esc(applications[type].name)}">${frame}${shape}</svg>`;
}
function setLoadEditor(type){
 $('load-type').value=type;const a=applications[type],cfg=loadConfig[type];$('application-title').textContent=a.name;$('application-text').textContent=a.text;$('load-formula').textContent=a.formula;$('application-visual').innerHTML=appSVG(type);$('load-parameter-controls').replaceChildren();
 for(const spec of a.params)slider($('load-parameter-controls'),...spec,cfg,()=>teachLoad());
 cfg.variants.forEach((v,i)=>$('variant-'+(i+1)).value=v);renderLoadCharts();if(teacherReady)teachLoad();
}
function loadData(type,scale,config=loadConfig[type],motorParams=params){
 const p={...motorParams,...config,...Object.fromEntries(['nominalVoltage','ratedVoltage','baseFrequency','maxFrequency','voltageMode','controlMode','frequencyTarget','polePairs','nominalSpeed','nominalTorque','slipRpm','magCurrent','torqueConstant','copper','iron','maxTorque','regen'].map(k=>[k,motorParams[k]])),loadType:type,loadScale:scale};
 return Array.from({length:181},(_,i)=>{const n=i*10,w=M.rad(n),T=M.magnitude(w,p,type,scale),el=M.electrical(w,T,p);const limit=M.availableTorque?M.availableTorque(w,p):p.maxTorque*Math.min(1,p.baseFrequency/Math.max(Math.abs(el.f),p.baseFrequency));return {n,T,Pm:T*w,...el,feasible:T<=limit+.00001&&n<=(p.maxFrequency||100)*60/p.polePairs};});
}
function renderLoadCharts(){
 if(!Object.keys(loadCharts).length)return;const metric=$('load-metric').value,labels={T:'Koppel (Nm)',Pel:'Elektrisch motorvermogen (W)',Pm:'Mechanisch vermogen (W)',I:'Motorstroom (A)',U:'Lijnspanning (V)',PF:'Arbeidsfactor (-)'};
 for(const [type,c] of Object.entries(loadCharts)){c.yLabel=labels[metric];const cfg=loadConfig[type],previous=loadComparisons[type],before=previous?previous.cfg.variants.map((v,i)=>({name:`Vóór ${['A','B','C'][i]} · ${M.loadNames[previous.type]} · ${fmt(v,1)}`,color:'#8298b2',dashed:true,points:loadData(previous.type,v,previous.cfg,previous.motor).filter(s=>s.feasible).map(s=>({x:s.n,y:s[metric],note:`Vorige berekende belastingslijn: T = ${fmt(s.T)} Nm; Pmech = Tω = ${fmt(s.Pm,0)} W. Geen versnelling: dit is een stationair werkingspunt.`}))})):[];c.setData([...before,...cfg.variants.map((v,i)=>({name:`${previous?'Na ':''}${['A','B','C'][i]} · factor ${fmt(v,1)}`,color:palette[i],points:loadData(type,v).filter(s=>s.feasible).map(s=>({x:s.n,y:s[metric],note:`${M.loadNames[type]}: T = ${fmt(s.T)} Nm; Pmech = Tω = ${fmt(s.Pm,0)} W. ${applications[type].formula}. Elektrische waarden zijn schattingen.`}))}))],{reset:true});}
}
function runInertia(quiet=false){
 if(quiet!==true)playing=false;const oldRuns=inertiaRuns,oldSettings=lastInertiaState;try{
 const js=['j1','j2','j3'].map(id=>Number($(id).value));if(js.some(j=>!Number.isFinite(j)||j<.005||j>2))throw Error('Kies drie J-waarden tussen 0,005 en 2 kg·m².');
 const limited=$('inertia-method').value==='limited';
 const target=Number($('inertia-target').value),T0=Number($('inertia-load').value);
 inertiaRuns=js.map((J,i)=>{const p=M.validate({...params,controlMode:'speed',J,initial:0,target,T0,loadType:'constant',loadScale:1,feedforward:!limited,rampUp:limited?.05:params.rampUp,rampDown:limited?.05:params.rampDown});const d=M.simulate(p,p.duration);return {name:'Reeks '+['A','B','C'][i],params:p,data:d.data,events:d.events};});
 renderInertia(oldRuns);estimateJ();teachInertia(oldRuns,oldSettings);if(quiet!==true)notify('Drie aanlopen berekend met dezelfde motor en belasting. Kies een tijdsinterval in de rechtergrafiek om J terug te rekenen.');
 }catch(e){notify(e.message);}
}
function renderInertia(oldRuns=[]){
 const blind=$('blind').checked;
 const oldM=oldRuns.map(r=>({...series(r.data,'M','Vóór '+r.name,'#8298b2'),dashed:true})),oldN=oldRuns.map(r=>({...series(r.data,'n','Vóór '+r.name,'#8298b2'),dashed:true}));charts.inertiaM.setData([...oldM,...inertiaRuns.map((r,i)=>series(r.data,'M',(oldRuns.length?'Na ':'')+r.name+(blind?'':` · J ${fmt(r.params.J,3)}`),palette[i]))],{reset:true});charts.inertiaN.setData([...oldN,...inertiaRuns.map((r,i)=>series(r.data,'n',(oldRuns.length?'Na ':'')+r.name+(blind?'':` · J ${fmt(r.params.J,3)}`),palette[i]))],{reset:true});
 if(!inertiaRuns.length)return;
 $('inertia-metrics').innerHTML=`<h2>Vergelijking van de respons</h2><table class="data-table"><thead><tr><th>Reeks</th><th>${blind?'J verborgen':'J (kg·m²)'}</th><th>Piek |M| (Nm)</th><th>Piek |α| (rad/s²)</th><th>Blijvend binnen 2% (s)</th><th>Eind n (tpm)</th></tr></thead><tbody>${inertiaRuns.map(r=>{const z=M.metrics(r.data,r.params.target);return `<tr><td>${r.name}</td><td>${blind?'?':fmt(r.params.J,3)}</td><td>${fmt(z.maxM)}</td><td>${fmt(z.maxA)}</td><td>${z.settled===null?'Niet bereikt':fmt(z.settled)}</td><td>${fmt(z.final,0)}</td></tr>`;}).join('')}</tbody></table><p class="control-note">Bij een haalbare gecompenseerde ramp kan de aanlooptijd vrijwel gelijk blijven terwijl het koppel toeneemt met J. Bij koppelbegrenzing duurt de aanloop met grotere J langer. J is hier de totale naar de motoras herleide traagheid.</p>`;
}
function estimateJ(){
 try{if(!inertiaRuns.length)throw Error('Bereken eerst de drie aanlopen.');const r=inertiaRuns[Number($('estimate-series').value)],z=M.estimate(r.data,Number($('interval-start').value),Number($('interval-end').value));charts.inertiaN.selection=[z.t1,z.t2];charts.inertiaN.draw();
 const steps=[['Tijdsinterval Δt',fmt(z.dt)+' s',`${fmt(z.t2)} − ${fmt(z.t1)} s`],['Toerentalverschil Δn',fmt(z.dn)+' tpm','n₂ − n₁'],['Hoeksnelheidsverschil Δω',fmt(z.dw)+' rad/s','2π · Δn / 60'],['Gemiddelde versnelling α',fmt(z.alpha)+' rad/s²','Δω / Δt'],['Gemiddeld netto koppel',fmt(z.meanNet)+' Nm','∫(M − T)dt / Δt'],['Berekend traagheidsmoment',fmt(z.J,5)+' kg·m²','Gemiddeld netto koppel / α']];
 $('estimate-result').innerHTML=`<div class="calc-steps">${steps.map(([label,value,formula])=>`<div class="calc-step"><span>${label}</span><strong>${value}</strong><small>${formula}</small></div>`).join('')}</div><p class="calc-result">Koppelimpuls = <b>${fmt(z.impulse,4)} N·m·s</b>. De integraal telt de werkelijk berekende netto koppelbijdrage van iedere integratiestap op; er wordt geen ingestelde J in de schattingsformule ingevuld. ${$('blind').checked?'<button id="reveal-j">Vergelijk nu met de verborgen waarde</button>':`Ingesteld J = <b>${fmt(z.actual,5)} kg·m²</b>; relatieve afwijking ${fmt(z.error*100,6)}%.`}</p>`;
 if(teacherReady)teacherPanels.traagheid.report(`Berekening uit gesimuleerde grafieken van ${r.name}, geen echte metingen: t₁ = ${fmt(z.t1)} s, t₂ = ${fmt(z.t2)} s, Δn = ${fmt(z.dn)} tpm en Δω = ${fmt(z.dw)} rad/s. Gemiddeld netto koppel ${fmt(z.meanNet)} Nm en α = ${fmt(z.alpha)} rad/s² geven J = gemiddeld(M − T)/α = ${fmt(z.J,5)} kg·m². Met de koppelimpuls is hetzelfde resultaat J = ${fmt(z.impulse,4)} / ${fmt(z.dw)}. ${$('blind').checked?'De ingestelde referentiewaarde blijft verborgen.':`De relatieve afwijking ten opzichte van de ingestelde totale J is ${fmt(z.error*100,6)}%.`} Hetzelfde venster is op beide tijdassen gebruikt; stilstand of een vrijwel horizontaal n(t)-segment zou deze berekening onbetrouwbaar maken.`);
 if($('reveal-j'))$('reveal-j').onclick=()=>{notify(`Ingesteld J = ${fmt(z.actual,5)} kg·m²; berekend ${fmt(z.J,5)} kg·m². Relatieve afwijking ${fmt(z.error*100,6)}%.`);};
 }catch(e){$('estimate-result').innerHTML=`<p class="blind-note">${esc(e.message)}</p>`;}
}

const theory=[
 ['Frequentieomvormer en snelheidsregeling','Een gelijkrichter maakt een DC-tussenkring. Een geschakelde inverter vormt daaruit een wisselspanning met instelbare frequentie en amplitude. Hier volgen we een regelkundige benadering: een rampgenerator levert de snelheidsreferentie; een PI-regelaar en optionele last- en inertiecompensatie vragen koppel. Een eerste-ordevertraging en koppelgrens benaderen de motor- en stroomregeling.','Mvraag = Kp(ωref − ω) + ∫Ki(ωref − ω)dt + compensatie'],
 ['Asynchrone motor synchroon toerental en slip','Het statordraaiveld draait synchroon met de voedingsfrequentie. De rotor heeft een snelheidsverschil nodig voor inductie en koppel. De hier getoonde frequentie wordt geschat uit de werkelijke rotorsnelheid en een koppelafhankelijke slipfrequentie. Ze is geen opgelost elektromagnetisch veldmodel. Het aantal poolparen is p.','ns = 60f / p · s = (ns − n) / ns'],
 ['Koppel vermogen en energie','Koppel verandert het impulsmoment. Vermogen is de snelheid waarmee energie wordt overgedragen. Een motor kan bij nul snelheid wel koppel en stroom hebben, terwijl zijn mechanisch vermogen nul is. De rotatie-energie groeit met J en met het kwadraat van de hoeksnelheid.','Pmech = Mω · Ekin = ½Jω² · ω = 2πn / 60'],
 ['Belasting en dynamisch evenwicht','Bij stationaire snelheid is het motorkoppel gelijk aan het tegenwerkende koppel. Tijdens positieve versnelling is er een positief netto koppel nodig. Deze simulator gebruikt passieve lasten: hun teken keert om met de draairichting. Bij stilstand past de statische reactie zich aan tot de losbreekdrempel. Zo kan wrijving de stilstaande motor niet vanzelf achteruit laten draaien.','Jα = Mmotor − Mbelasting · α = 0 ⇒ Mmotor = Mbelasting'],
 ['De vier kwadranten','De M,n-grafiek heeft M horizontaal en n verticaal. I: M > 0, n > 0, motor vooruit. II: M < 0, n > 0, generatorisch remmen vooruit. III: M < 0, n < 0, motor achteruit. IV: M > 0, n < 0, generatorisch remmen achteruit. Verlaag de consigne tot een negatieve waarde om de overgangen te onderzoeken.','Motorisch: Mω > 0 · generatorisch: Mω < 0'],
 ['Versnellen vertragen en inertie','Bij hetzelfde netto koppel verlaagt een grotere J de versnelling. Bij een opgelegde snelheidsramp vraagt een grotere J juist meer koppel. Als de motor dat extra koppel kan leveren, kan de aanlooptijd gelijk blijven. Een grotere traagheid veroorzaakt dus niet onder alle regelomstandigheden een langere aanloop.','α = (M − T) / J · M = T + Jα'],
 ['Vrij uitlopen en elektrisch remmen','Bij vrij uitlopen verdwijnt het actieve motorkoppel na een korte fluxvertraging; de last remt de as af. Bij een gecontroleerde remramp kan de motor negatief koppel leveren. Een motor kan ook vertragen terwijl zijn koppel nog positief is, als de last groter is. Generatorbedrijf bewijst niet dat energie terugvloeit naar het net: een remweerstand zet de energie om in warmte. Een regeneratieve netomvormer kan ze terugvoeren.','Bij n > 0: M < T ⇒ vertraging · M < 0 ⇒ generatorisch'],
 ['Vijf belastingswetten','Constant koppel past bij een transportband met ongeveer constante kracht. Een viskeuze belasting stijgt ongeveer lineair met snelheid. Ventilatoren en centrifugaalpompen hebben onder vergelijkbare omstandigheden een kwadratisch koppel. Losbreekkoppel beschrijft een hoge statische wrijvingsdrempel. Constant procesvermogen past bijvoorbeeld bij een wikkelproces met constante kracht en bandsnelheid, binnen zijn bedrijfsgebied.','T = T₀ · T = T₀ + b|ω| · T = T₀ + kω² · T ≈ P/|ω|'],
 ['Elektrische schattingen begrijpen','De motorspanning volgt bij benadering U/f tot de basisspanning. Boven de basisfrequentie daalt het beschikbare koppel door veldverzwakking. Stroom, actieve verliezen en arbeidsfactor komen uit een eenvoudige fundamentele-golfbenadering. Pel is het getekende actieve vermogen aan de motorklemmen; Pnet en Prem worden apart berekend. PF wordt getekend weergegeven om de energierichting te tonen. PWM-harmonischen en echte netarbeidsfactor worden niet opgelost.','Pel = Mω + Pverlies · PF = Pel / (√3 · U · I)'],
 ['Traagheid uit een interval','Kies twee punten met voldoende snelheidsverschil. Bepaal Δω en integreer het netto koppel over het tijdsinterval. Deel de koppelimpuls door Δω. Dit is ook bruikbaar als de versnelling niet constant is. De uitkomst is de totale effectieve traagheid. Voor alleen de belasting moet een bekende motor- en banktraagheid worden afgetrokken.','J = ∫(M − T)dt / Δω = gemiddeld(M − T) / gemiddeld(α)']
];
const sourceHTML='<h3>Bronnen en afbakening</h3><p>Opdrachtvolgorde en instellingen: cursusaandrijvingen2025 (3).pdf, hoofdstuk 8, p. 56–58. De opstelling verwijst naar hoofdstuk 7.</p><p><a href="https://www.leroy-somer.com/documentation_pdf/notices_pdf/4467a_fr.pdf" target="_blank" rel="noopener">Officiële Leroy-Somer handleiding 4467 fr, 2010.01/a</a>, p. 19–20: ApILE-werkwijzen. Deze simulator gebruikt de vijf gevraagde onderwijswetten; geen claim van exacte ApILE-software-identiteit. De motorparameters zijn aanpasbare voorbeelden, geen geverifieerde plaatgegevens van de echte bank.</p>';
const assumptions=`<p>Deze onafhankelijke onderwijssimulator draait volledig in de browser, zonder netwerkverzoeken, accounts, API-sleutels of betaalde bibliotheken. Er is geen verbinding met een echte testbank.</p><h3>Mechanica en regeling</h3><ul><li>Eén starre as met constante totale effectieve J, per integratie-interval. Geen speling, torsie-elasticiteit of temperatuurmodel.</li><li>Vaste tijdstap 2 ms; registratie om de 20 ms. De snelheid volgt uit een expliciete impulsupdate. Het motorkoppel volgt een eerste-ordevertraging met exponentiële update.</li><li>PI-snelheidsregeling met begrensde integraal, optionele last- en inertiecompensatie, rampgenerator en koppelbegrenzing. Dit benadert een geregelde asynchrone aandrijving; geen volledig inductiemachine-equivalent schema.</li><li>Alle lasten zijn passief, ook bij achteruit draaien. Zwaartekrachtlasten die de motor actief aandrijven worden niet gemodelleerd.</li><li>De constant-vermogenslast krijgt nabij nul een eindige koppelgrens. Losbreekwrijving wordt met een Stribeck-benadering en een statische houdreactie gemodelleerd.</li><li>Wijzigen van J tijdens een opname wisselt het effectieve model. Het simuleert geen fysische koppeling van massa met behoud van impulsmoment. De J-rekenfunctie weigert zo’n interval.</li></ul><h3>Elektrische benadering</h3><ul><li>Geschatte slipfrequentie is evenredig met motorkoppel. U/f met een benaderde resistieve spanningsboost bij lage frequentie wordt tot de basisspanning begrensd; het beschikbare koppel daalt boven de basisfrequentie.</li><li>Pel = Mω plus positieve benaderde koper- en ijzerverliezen. De effectieve lijnstroom wordt benaderd uit het grootste van koppelstroom en benodigde actieve stroom, gecombineerd met een magnetiseringscomponent. Geen PWM-rimpel, harmonischen, saturatie of thermische beveiliging.</li><li>Motorisch/generatorisch wordt uit Mω bepaald. Bij een remweerstand is negatief motorklemvermogen warmte; uitsluitend met de geselecteerde regeneratieve netomvormer is Pnet negatief.</li><li>Spanning, stroom, PF en Pel zijn onderwijswaarden. Gebruik ze niet als exacte dimensionering van een echte installatie.</li></ul><h3>Offline en opslag</h3><p>Alles werkt via index.html. Alleen wanneer je zelf een bronlink aanklikt, opent een externe pagina. Browseropslag wordt uitsluitend lokaal gebruikt voor opnamen en eigen antwoorden. Maximaal acht bewaarde opnamen en 120 seconden per dynamische opname; exporteer CSV of JSON om resultaten onafhankelijk van browseropslag te bewaren.</p>${sourceHTML}`;
$('assumptions-content').innerHTML=assumptions+'<h3>Frequentie en spanning instellen</h3><p>Bij de frequentieconsigne werkt dit model als een scalaire U/f-aandrijving: de ramp stuurt het synchrone draaiveld en een vereenvoudigde kleine-slipwet bepaalt het koppel. De rotor komt onder last bij een ander toerental uit. De PI-snelheidsregelaar en last-/inertiecompensatie zijn alleen actief in toerentalmodus. Het voorspelde belaste eindtoerental is niet gegarandeerd haalbaar bij overbelasting.</p><p>Beschikbare motorlijnspanning is de effectieve motorspanning die de inverter maximaal kan leveren. Dit is geen invoer voor de netspanning of DC-tussenkringspanning. Nominale motorlijnspanning is de afzonderlijke motorreferentie. Bij vaste spanning en lage frequentie kan overflux optreden; de extra magnetiseringsstroom is een begrensde onderwijsbenadering en geen thermisch beveiligingsmodel. Controleer in het echte labo de kenplaat, schakeling, frequentieregelaar en stroomgrenzen.</p>';
$('theory-content').innerHTML=theory.map(([title,text,formula],i)=>`<details class="card theory-card" ${i===0?'open':''}><summary>${title}</summary><p>${text}</p><div class="formula-block">${formula}</div></details>`).join('')+`<section class="card theory-card">${sourceHTML}<p><a href="HANDLEIDING.html" target="_blank">Lokale handleiding en testinstructies</a></p></section>`;
const exercises=[
 ...Object.entries(experiments).map(([id,e])=>({id,label:e.label,task:`Voer ${e.label} uit met J = 0,100 kg·m². ${id==='d2'||id==='d4'?'Vergelijk vrij uitlopen en gecontroleerd afremmen.':'Bewaar deze actie op een afzonderlijke M,n-grafiek.'}`,answer:id==='d1'||id==='d3'||id==='d5'?'Tijdens versnelling moet M groter zijn dan T. Het verschil Jα levert het versnellingskoppel. Stationair daalt M naar de benodigde belasting. Bij een grotere last neemt de koppelvraag toe; bij begrenzing kan de snelheid de ramp niet volgen.':'Tijdens vertraging is het netto koppel tegengesteld aan de snelheid. Het motorkoppel zelf kan nog positief blijven. Generatorbedrijf treedt pas op als M en n tegengesteld teken krijgen. Bij vrij uitlopen is het actieve koppel na de fluxvertraging nul en remt de last de as af.'})),
 ...Object.keys(M.loadNames).map((type,i)=>({id:'l'+i,type,label:`B${i+1} · ${M.loadNames[type]}`,task:'Neem deze belastingslijn op bij drie parameterinstellingen. Koppel de wet aan een industriële toepassing en onderzoek minstens één elektrische grootheid.',answer:applications[type].text+' Mechanisch vermogen is Tω. Meer last vraagt doorgaans meer koppelstroom en actief vermogen; de elektrische grafieken zijn vereenvoudigde schattingen.'})),
 {id:'j',label:'J1 · Drie traagheidsmomenten en J berekenen',task:'Gebruik T = 2,5 Nm en drie verschillende J-waarden. Vergelijk M(t) en n(t) naast elkaar en bereken elke J uit een gekozen tijdsinterval.',answer:'Een grotere J verlaagt de versnelling bij hetzelfde netto koppel. Een gecompenseerde snelheidsramp kan de aanlooptijd gelijk houden door extra koppel te vragen. Integreer M − T over het venster en deel door Δω. Dit geeft de totale effectieve J, niet automatisch uitsluitend de belasting.'}
];
$('exercise-select').innerHTML=exercises.map((e,i)=>`<option value="${i}">${esc(e.label)}</option>`).join('');
let answers={};try{answers=JSON.parse(localStorage.getItem('drivelab-answers-v1')||'{}');}catch{}
function saveAnswer(){const key=$('exercise-select').value;answers[key]={prediction:$('prediction').value,explanation:$('own-explanation').value};try{localStorage.setItem('drivelab-answers-v1',JSON.stringify(answers));}catch{}}
function showExercise(){const i=$('exercise-select').value,e=exercises[i];$('exercise-task').textContent=e.task;$('prediction').value=answers[i]?.prediction||'';$('own-explanation').value=answers[i]?.explanation||'';$('model-answer').hidden=true;$('exercise-progress').textContent='Voorspel eerst het resultaat; laad daarna de instellingen.';}
function prepareExercise(run=false){
 saveAnswer();const e=exercises[Number($('exercise-select').value)];
 if(e.type){setLoadEditor(e.type);$('load-metric').value='T';renderLoadCharts();if(run){setTab('belastingen');notify('Vergelijk de drie varianten. Keer daarna terug naar de oefenmodus voor je verklaring.');}}
 else if(e.id==='j'){$('inertia-load').value=2.5;$('inertia-target').value=1400;['j1','j2','j3'].forEach((id,i)=>$(id).value=[.05,.1,.2][i]);if(run){setTab('traagheid');runInertia();}}
 else{$('experiment').value=e.id;loadExperiment(e.id);if(run){setTab('dynamiek');runStart();}}
 $('exercise-progress').textContent=run?'De resultaten staan in het bijbehorende onderdeel. Keer hier terug om je verklaring te noteren.':'Instellingen geladen. Je voorspelling en verklaring blijven bewaard.';
}

// Build the controls and all native canvas plots once; the simulation has no external dependencies.
for(const [host,specs] of [[ $('core-controls'),[['target','Consigne (tpm)',-2500,2500,50],['T0','Constant lastkoppel (Nm)',0,30,.1],['J','Totale traagheid J (kg·m²)',.005,1,.005],['rampUp','Ramp omhoog 0 → nominaal (s)',.1,20,.1],['rampDown','Ramp omlaag nominaal → 0 (s)',.1,20,.1],['initial','Starttoerental (tpm)',-2500,2500,50]]],[$('advanced-controls'),[['maxTorque','Koppelgrens (Nm)',.5,40,.5],['tau','Regelvertraging (s)',.002,.5,.002],['kp','PI Kp (Nms/rad)',.01,2,.01],['ki','PI Ki (Nm/rad)',0,5,.05],['nominalSpeed','Nominaal toerental (tpm)',500,2400,50],['baseFrequency','Basisfrequentie (Hz)',20,100,1],['polePairs','Aantal poolparen',1,6,1],['nominalVoltage','Nominale lijnspanning (V)',24,690,1],['nominalTorque','Referentiekoppel slip (Nm)',1,30,.5],['magCurrent','Magnetiseringsstroom (A)',0,5,.1],['torqueConstant','Koppelconstante (Nm/A)',.1,10,.1],['copper','Koperverliesfactor (W/A²)',0,30,.5],['iron','Ijzerverlies bij basisf (W)',0,150,1],['duration','Opnameduur (s)',1,120,1]]],[$('dynamic-load-controls'),[['b','Lineaire factor b',0,.15,.001],['k','Kwadratische factor k',0,.001,.00001],['breakaway','Losbreekkoppel (Nm)',0,30,.5],['breakSpeed','Losbreeksnelheid ωs (rad/s)',.1,40,.5],['power','Constant procesvermogen (W)',0,2000,25],['powerCap','Koppellimiet constant vermogen',.1,30,.5]]]])for(const spec of specs)addMainControl(host,...spec);
for(const spec of [['frequencyTarget','Frequentieconsigne (Hz)',-200,200,1],['maxFrequency','Maximale uitgangsfrequentie (Hz)',1,200,1]])addMainControl($('core-controls'),...spec);
for(const spec of [['ratedVoltage','Nominale motorlijnspanning op kenplaat (V)',24,690,1],['slipRpm','Referentieslip bij referentiekoppel (tpm)',1,400,1]])addMainControl($('advanced-controls'),...spec);
for(const c of controlInputs.values())if(c.key==='nominalVoltage'){c.number.closest('label').querySelector('.slider-label>span').textContent='Beschikbare motorlijnspanning (V)';c.number.setAttribute('aria-label','Beschikbare motorlijnspanning (V)');c.range.setAttribute('aria-label','Beschikbare motorlijnspanning (V) schuifregelaar');}
