$('start').onclick=runStart;$('stop').onclick=stopMotor;$('pause').onclick=()=>{playing=!playing;if(playing&&drive.t===0)drive.command(pendingAction);if(drive.t>=params.duration)playing=false;paint();if(!playing)reportActual(drive,'Gepauzeerde labo-actie');};
$('step').onclick=()=>{playing=false;if(drive.t===0)drive.command(pendingAction);if(drive.t<params.duration)drive.advance(.02);paint();};
